CREATE TABLE public.chat_contacts(owner_user_id uuid NOT NULL,contact_user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_user_id,contact_user_id),CHECK(owner_user_id<>contact_user_id));
GRANT SELECT ON public.chat_contacts TO authenticated;
GRANT ALL ON public.chat_contacts TO service_role;
ALTER TABLE public.chat_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own contacts" ON public.chat_contacts FOR SELECT TO authenticated USING(owner_user_id=auth.uid());
CREATE TABLE public.chat_blocks(blocker_user_id uuid NOT NULL,blocked_user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_user_id,blocked_user_id),CHECK(blocker_user_id<>blocked_user_id));
GRANT SELECT ON public.chat_blocks TO authenticated;
GRANT ALL ON public.chat_blocks TO service_role;
ALTER TABLE public.chat_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own blocks" ON public.chat_blocks FOR SELECT TO authenticated USING(blocker_user_id=auth.uid());
CREATE TABLE public.chat_discovery_limits(user_id uuid PRIMARY KEY,window_started_at timestamptz NOT NULL,attempts integer NOT NULL);
GRANT ALL ON public.chat_discovery_limits TO service_role;
ALTER TABLE public.chat_discovery_limits ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.chat_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_user_id uuid NOT NULL,reported_user_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved')));
GRANT SELECT,UPDATE(status) ON public.chat_reports TO authenticated;
GRANT ALL ON public.chat_reports TO service_role;
ALTER TABLE public.chat_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admins review reports" ON public.chat_reports FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY "admins resolve reports" ON public.chat_reports FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE INDEX chat_blocks_reverse_idx ON public.chat_blocks(blocked_user_id,blocker_user_id);
CREATE INDEX chat_reports_review_idx ON public.chat_reports(status,created_at DESC);
CREATE FUNCTION public.chat_users_blocked(_user uuid,_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.chat_blocks WHERE (blocker_user_id=_user AND blocked_user_id=_other) OR(blocker_user_id=_other AND blocked_user_id=_user)); $$;
REVOKE ALL ON FUNCTION public.chat_users_blocked(uuid,uuid) FROM PUBLIC,anon;
CREATE FUNCTION public.consume_chat_discovery_attempt() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE n integer; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=auth.uid() AND status='verified') THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501'; END IF; INSERT INTO public.chat_discovery_limits VALUES(auth.uid(),now(),1) ON CONFLICT(user_id) DO UPDATE SET window_started_at=CASE WHEN public.chat_discovery_limits.window_started_at<now()-interval '1 minute' THEN now() ELSE public.chat_discovery_limits.window_started_at END,attempts=CASE WHEN public.chat_discovery_limits.window_started_at<now()-interval '1 minute' THEN 1 ELSE least(public.chat_discovery_limits.attempts+1,31) END RETURNING attempts INTO n; RETURN n<=30; END; $$;
REVOKE ALL ON FUNCTION public.consume_chat_discovery_attempt() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.find_chat_user_by_email(_email text) RETURNS TABLE(user_id uuid,full_name text,role text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.consume_chat_discovery_attempt() THEN RETURN; END IF; RETURN QUERY SELECT p.user_id,p.full_name::text,p.role FROM auth.users u JOIN public.profiles p ON p.user_id=u.id WHERE lower(u.email)=lower(trim(_email)) AND p.status='verified' AND p.user_id<>auth.uid() AND NOT public.chat_users_blocked(auth.uid(),p.user_id) LIMIT 1; END; $$;
CREATE FUNCTION public.add_chat_contact_by_email(_email text) RETURNS TABLE(user_id uuid,full_name text,role text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE target uuid; BEGIN SELECT f.user_id INTO target FROM public.find_chat_user_by_email(_email) f; IF target IS NULL THEN RAISE EXCEPTION 'No reachable contact' USING ERRCODE='P0002'; END IF; INSERT INTO public.chat_contacts(owner_user_id,contact_user_id) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING; RETURN QUERY SELECT p.user_id,p.full_name::text,p.role FROM public.profiles p WHERE p.user_id=target; END; $$;
CREATE FUNCTION public.create_direct_chat_by_email(_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE target uuid; conv uuid; BEGIN SELECT f.user_id INTO target FROM public.find_chat_user_by_email(_email) f; IF target IS NULL THEN RAISE EXCEPTION 'No reachable contact' USING ERRCODE='P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(least(auth.uid()::text,target::text)||':'||greatest(auth.uid()::text,target::text),0)); SELECT c.id INTO conv FROM public.conversations c WHERE c.type='direct' AND EXISTS(SELECT 1 FROM public.conversation_members m WHERE m.conversation_id=c.id AND m.user_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.conversation_members m WHERE m.conversation_id=c.id AND m.user_id=target) AND(SELECT count(*) FROM public.conversation_members m WHERE m.conversation_id=c.id)=2 ORDER BY c.created_at LIMIT 1; IF conv IS NULL THEN INSERT INTO public.conversations(type,created_by) VALUES('direct',auth.uid()) RETURNING id INTO conv; INSERT INTO public.conversation_members(conversation_id,user_id,role) VALUES(conv,auth.uid(),'admin'),(conv,target,'member'); END IF; INSERT INTO public.chat_contacts(owner_user_id,contact_user_id) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING; RETURN conv; END; $$;
CREATE FUNCTION public.add_chat_contact(_contact_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL OR auth.uid()=_contact_user_id OR public.chat_users_blocked(auth.uid(),_contact_user_id) OR NOT EXISTS(SELECT 1 FROM public.conversation_members m JOIN public.conversation_members t USING(conversation_id) JOIN public.conversations c ON c.id=m.conversation_id WHERE m.user_id=auth.uid() AND t.user_id=_contact_user_id AND c.type='direct') THEN RAISE EXCEPTION 'Contact unavailable' USING ERRCODE='42501'; END IF; INSERT INTO public.chat_contacts(owner_user_id,contact_user_id) VALUES(auth.uid(),_contact_user_id) ON CONFLICT DO NOTHING; END; $$;
CREATE FUNCTION public.list_chat_contacts() RETURNS TABLE(user_id uuid,email text,full_name text,role text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p.user_id,u.email::text,p.full_name::text,p.role FROM public.chat_contacts c JOIN public.profiles p ON p.user_id=c.contact_user_id JOIN auth.users u ON u.id=p.user_id WHERE c.owner_user_id=auth.uid() AND NOT public.chat_users_blocked(auth.uid(),p.user_id) ORDER BY p.full_name; $$;
CREATE FUNCTION public.get_chat_member_profiles(_user_ids uuid[]) RETURNS TABLE(user_id uuid,full_name text,role text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p.user_id,p.full_name::text,p.role FROM public.profiles p WHERE p.user_id=ANY(_user_ids) AND EXISTS(SELECT 1 FROM public.conversation_members m JOIN public.conversation_members t USING(conversation_id) WHERE m.user_id=auth.uid() AND t.user_id=p.user_id) AND NOT public.chat_users_blocked(auth.uid(),p.user_id); $$;
CREATE FUNCTION public.get_chat_contact_details(_contact_user_id uuid) RETURNS TABLE(user_id uuid,email text,full_name text,role text,phone_number text,mutual boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p.user_id,u.email::text,p.full_name::text,p.role,CASE WHEN EXISTS(SELECT 1 FROM public.chat_contacts r WHERE r.owner_user_id=p.user_id AND r.contact_user_id=auth.uid()) THEN p.phone_number::text ELSE NULL END,EXISTS(SELECT 1 FROM public.chat_contacts r WHERE r.owner_user_id=p.user_id AND r.contact_user_id=auth.uid()) FROM public.chat_contacts c JOIN public.profiles p ON p.user_id=c.contact_user_id JOIN auth.users u ON u.id=p.user_id WHERE c.owner_user_id=auth.uid() AND p.user_id=_contact_user_id AND NOT public.chat_users_blocked(auth.uid(),p.user_id) AND EXISTS(SELECT 1 FROM public.conversation_members m JOIN public.conversation_members t USING(conversation_id) JOIN public.conversations conv ON conv.id=m.conversation_id WHERE m.user_id=auth.uid() AND t.user_id=p.user_id AND conv.type='direct'); $$;
CREATE FUNCTION public.block_chat_user(_blocked_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL OR auth.uid()=_blocked_user_id OR NOT EXISTS(SELECT 1 FROM public.conversation_members m JOIN public.conversation_members t USING(conversation_id) WHERE m.user_id=auth.uid() AND t.user_id=_blocked_user_id) THEN RAISE EXCEPTION 'Shared conversation required' USING ERRCODE='42501'; END IF; INSERT INTO public.chat_blocks(blocker_user_id,blocked_user_id) VALUES(auth.uid(),_blocked_user_id) ON CONFLICT DO NOTHING; END; $$;
CREATE FUNCTION public.report_chat_user(_reported_user_id uuid,_conversation_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL OR auth.uid()=_reported_user_id OR _reason IS NULL OR length(trim(_reason)) NOT BETWEEN 1 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.conversation_members m JOIN public.conversation_members t USING(conversation_id) WHERE m.user_id=auth.uid() AND t.user_id=_reported_user_id AND m.conversation_id=_conversation_id) THEN RAISE EXCEPTION 'Invalid report' USING ERRCODE='42501'; END IF; INSERT INTO public.chat_reports(reporter_user_id,reported_user_id,conversation_id,reason) VALUES(auth.uid(),_reported_user_id,_conversation_id,trim(_reason)) RETURNING id INTO result; RETURN result; END; $$;
CREATE FUNCTION public.can_send_chat_message(_conversation uuid,_sender uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT _sender=auth.uid() AND public.is_conversation_member(_conversation,_sender) AND NOT EXISTS(SELECT 1 FROM public.conversations c JOIN public.conversation_members m ON m.conversation_id=c.id WHERE c.id=_conversation AND c.type='direct' AND m.user_id<>_sender AND public.chat_users_blocked(_sender,m.user_id)); $$;
REVOKE ALL ON FUNCTION public.can_send_chat_message(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_send_chat_message(uuid,uuid) TO authenticated;
DROP POLICY IF EXISTS "members can send messages" ON public.messages;
CREATE POLICY "unblocked members can send messages" ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.can_send_chat_message(conversation_id,auth.uid()));
CREATE FUNCTION public.get_user_conversations(_limit integer DEFAULT 50,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT coalesce(jsonb_agg(row_data ORDER BY last_message_at DESC,id DESC),'[]'::jsonb) FROM(SELECT c.id,c.last_message_at,jsonb_build_object('id',c.id,'type',c.type,'title',c.title,'avatar_url',c.avatar_url,'created_by',c.created_by,'last_message_at',c.last_message_at,'members',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'last_read_at',m.last_read_at,'full_name',CASE WHEN public.chat_users_blocked(auth.uid(),m.user_id) THEN NULL ELSE p.full_name END,'avatar_url',NULL)),'[]'::jsonb) FROM public.conversation_members m LEFT JOIN public.profiles p ON p.user_id=m.user_id WHERE m.conversation_id=c.id),'last_message',(SELECT jsonb_build_object('id',msg.id,'body',msg.body,'sender_id',msg.sender_id,'attachment_name',msg.attachment_name,'created_at',msg.created_at) FROM public.messages msg WHERE msg.conversation_id=c.id AND msg.deleted_at IS NULL ORDER BY msg.created_at DESC,msg.id DESC LIMIT 1),'unread_count',(SELECT count(*) FROM public.messages msg WHERE msg.conversation_id=c.id AND msg.sender_id<>auth.uid() AND msg.created_at>mine.last_read_at AND msg.deleted_at IS NULL)) row_data FROM public.conversation_members mine JOIN public.conversations c ON c.id=mine.conversation_id WHERE mine.user_id=auth.uid() ORDER BY c.last_message_at DESC,c.id DESC LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) rows; $$;
REVOKE ALL ON FUNCTION public.find_chat_user_by_email(text),public.add_chat_contact_by_email(text),public.create_direct_chat_by_email(text),public.add_chat_contact(uuid),public.list_chat_contacts(),public.get_chat_member_profiles(uuid[]),public.get_chat_contact_details(uuid),public.block_chat_user(uuid),public.report_chat_user(uuid,uuid,text),public.get_user_conversations(integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.find_chat_user_by_email(text),public.add_chat_contact_by_email(text),public.create_direct_chat_by_email(text),public.add_chat_contact(uuid),public.list_chat_contacts(),public.get_chat_member_profiles(uuid[]),public.get_chat_contact_details(uuid),public.block_chat_user(uuid),public.report_chat_user(uuid,uuid,text),public.get_user_conversations(integer,integer) TO authenticated;
CREATE INDEX IF NOT EXISTS messages_live_unread_idx ON public.messages(conversation_id,created_at DESC) INCLUDE(sender_id) WHERE deleted_at IS NULL;